function statusClass(status){return status==="Em andamento"?"in-progress":status==="Finalizado"?"done":status==="Dropado"?"dropped":"queue"}
function gameStatusLabel(game){return game.status}
function escapeHtml(value){const div=document.createElement("div");div.textContent=value;return div.innerHTML}
function normalizeHttpUrl(value){if(!value)return "";try{const url=new URL(value);return url.protocol==="http:"||url.protocol==="https:"?url.href:""}catch(error){return ""}}
function statusToDb(status){return status==="Finalizado"?"completed":status==="Dropado"?"dropped":status==="Em andamento"?"playing":"queue"}
