function mapDbGame(row,taskStats={total:0,done:0}){const fallback="https://images.unsplash.com/photo-1542751371-adc38448a05e?auto=format&fit=crop&w=1200&q=85",progress=taskStats.total?Math.round(taskStats.done/taskStats.total*100):0;return{id:row.id,title:row.title,coverRef:row.cover_image_url||"",cover:row.cover_image_url?.startsWith("http")?row.cover_image_url:fallback,status:statusFromDb(row.status),isCompleted:row.is_completed,rating:row.rating,progress,meta:taskStats.total?`${taskStats.done} de ${taskStats.total} tarefas concluídas`:"Nenhuma tarefa cadastrada"}}
async function r2Request(path,options={}){const token=currentSession?.access_token;if(!token)throw new Error("Sessão inválida para imagens.");const response=await fetch(`${r2BaseUrl}${path}`,{...options,headers:{Authorization:`Bearer ${token}`,...options.headers}}),body=await response.json().catch(()=>({}));if(!response.ok)throw new Error(body.error||"Não foi possível acessar as imagens.");return body}
async function resolveStoredImage(value){if(!value?.startsWith("r2:"))return value||"";try{return(await r2Request("/sign",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({key:value.slice(3)})})).url}catch(error){return""}}
async function uploadOptimizedImage(image){const blob=await(await fetch(image.dataUrl)).blob(),result=await r2Request("/upload",{method:"POST",headers:{"Content-Type":blob.type},body:blob});return{ref:`r2:${result.key}`,url:result.url}}
async function deleteStoredImage(value){if(!value?.startsWith("r2:"))return true;try{await r2Request(`/image?key=${encodeURIComponent(value.slice(3))}`,{method:"DELETE"});return true}catch(error){console.warn("Não foi possível remover a imagem do R2.");return false}}
async function deleteStoredImages(values){const refs=[...new Set(values.filter(value=>value?.startsWith("r2:")))];if(!refs.length)return true;const results=await Promise.all(refs.map(deleteStoredImage));return results.every(Boolean)}
async function loadCloudGames(){const [gameResult,folderResult,itemResult]=await Promise.all([supabaseClient.from("games").select("*").order("created_at",{ascending:false}),supabaseClient.from("folders").select("id,game_id"),supabaseClient.from("note_items").select("folder_id,item_type,is_completed")]);if(gameResult.error){showToast("Não foi possível carregar sua biblioteca.");return}const folderToGame=new Map((folderResult.data||[]).map(folder=>[folder.id,folder.game_id])),statsByGame=new Map();(itemResult.data||[]).filter(item=>item.item_type==="task").forEach(item=>{const gameId=folderToGame.get(item.folder_id);if(!gameId)return;const stats=statsByGame.get(gameId)||{total:0,done:0};stats.total+=1;if(item.is_completed)stats.done+=1;statsByGame.set(gameId,stats)});games=(gameResult.data||[]).map(row=>mapDbGame(row,statsByGame.get(row.id)));await Promise.all(games.map(async game=>{if(game.coverRef.startsWith("r2:"))game.cover=await resolveStoredImage(game.coverRef)||game.cover}));activeGame=games[0]||null;renderGames();$("#sync-title").textContent="Sincronizado";$("#sync-subtitle").textContent="Dados protegidos na nuvem"}
function syncActiveGameTaskProgress(){if(!activeGame)return;const tasks=Object.values(notes).flat().filter(item=>item.type==="task"),done=tasks.filter(item=>item.done).length;activeGame.progress=tasks.length?Math.round(done/tasks.length*100):0;activeGame.meta=tasks.length?`${done} de ${tasks.length} tarefas concluídas`:"Nenhuma tarefa cadastrada";renderGames()}
async function loadCloudGameContent(gameId){const {data:folderRows,error:folderError}=await supabaseClient.from("folders").select("*").eq("game_id",gameId).order("position");if(folderError)throw folderError;const roots=(folderRows||[]).filter(row=>!row.parent_id),children=(folderRows||[]).filter(row=>row.parent_id);folders=roots.map(row=>({id:row.id,name:row.name,color:row.color_code}));subfolders=Object.fromEntries(roots.map(root=>[root.id,children.filter(row=>row.parent_id===root.id).map(row=>({id:row.id,name:row.name,color:row.color_code}))]));notes=Object.fromEntries(roots.map(root=>[root.id,[]]));const folderById=new Map((folderRows||[]).map(row=>[row.id,row]));if(folderRows?.length){const {data:itemRows,error:itemError}=await supabaseClient.from("note_items").select("*").in("folder_id",folderRows.map(row=>row.id)).order("created_at",{ascending:false});if(itemError)throw itemError;const resolvedRows=await Promise.all((itemRows||[]).map(async row=>({...row,resolvedImage:await resolveStoredImage(row.image_url)})));resolvedRows.forEach(row=>{const target=folderById.get(row.folder_id),rootId=target?.parent_id||target?.id;if(!rootId||!notes[rootId])return;notes[rootId].push({id:row.id,title:row.title,content:row.content_text,type:row.item_type,done:row.is_completed,image:row.resolvedImage,imageRef:row.image_url||"",date:"Sincronizado",subfolder:target.parent_id?target.id:null})})}activeFolder=folders[0]?.id||null;activeSubfolder=null;expandedFolders=new Set(activeFolder?[activeFolder]:[]);syncActiveGameTaskProgress()}
async function createDefaultFoldersForGame(gameId){const rows=defaultFolders.map((folder,index)=>({game_id:gameId,name:folder.name,color_code:folder.color,position:index})),{data,error}=await supabaseClient.from("folders").insert(rows).select();if(error)throw error;return data}
function saveGames(){localStorage.setItem("checkpoint-games",JSON.stringify(games))}
function initializeEmptyStructure(){if(folders.length)return;folders=defaultFolders.map(folder=>({...folder}));notes=Object.fromEntries(folders.map(folder=>[folder.id,[]]));subfolders=Object.fromEntries(folders.map(folder=>[folder.id,[]]));saveStructure();activeFolder=folders[0].id;activeSubfolder=null}
function locationOptions(selectedFolder=activeFolder,selectedSubfolder=activeSubfolder){return folders.map(folder=>`<optgroup label="${escapeHtml(folder.name)}"><option value="${folder.id}|" ${folder.id===selectedFolder&&!selectedSubfolder?"selected":""}>${escapeHtml(folder.name)} (pasta principal)</option>${(subfolders[folder.id]||[]).map(child=>`<option value="${folder.id}|${child.id}" ${folder.id===selectedFolder&&child.id===selectedSubfolder?"selected":""}>↳ ${escapeHtml(child.name)}</option>`).join("")}</optgroup>`).join("")}
