function folderItems(folderId){return notes[folderId]||[]}
function visibleItems(){const items=folderItems(activeFolder);return activeSubfolder?items.filter(n=>n.subfolder===activeSubfolder):items}
function findFolderLocation(id){const root=folders.find(folder=>String(folder.id)===String(id));if(root)return{item:root,parentId:null,isRoot:true};for(const [parentId,children] of Object.entries(subfolders)){const item=children.find(folder=>String(folder.id)===String(id));if(item)return{item,parentId,isRoot:false}}return null}
function folderParentOptions(targetId,currentParentId=null){return`<option value="" ${!currentParentId?"selected":""}>Pasta principal</option>${folders.filter(folder=>String(folder.id)!==String(targetId)).map(folder=>`<option value="${folder.id}" ${String(folder.id)===String(currentParentId)?"selected":""}>Dentro de ${escapeHtml(folder.name)}</option>`).join("")}`}
function clearFolderDropState(){draggedFolderId=null;touchFolderDrag=null;touchDropTarget=null;touchDropPosition=null;clearTimeout(touchFolderTimer);document.body.classList.remove("folder-dragging","folder-touch-dragging");document.querySelectorAll(".drop-target,.drop-before,.drop-after,.is-dragging").forEach(element=>element.classList.remove("drop-target","drop-before","drop-after","is-dragging"))}
async function moveFolder(folderId,newParentId){const location=findFolderLocation(folderId),parentId=newParentId||null;if(!location)return false;if(String(folderId)===String(parentId)){showToast("Uma pasta não pode ficar dentro dela mesma.");return false}if(parentId&&!folders.some(folder=>String(folder.id)===String(parentId))){showToast("A pasta de destino não foi encontrada.");return false}if(location.isRoot&&parentId&&(subfolders[location.item.id]||[]).length){showToast("Mova primeiro as subpastas desta pasta antes de colocá-la dentro de outra.");return false}if(String(location.parentId||"")===String(parentId||""))return true;try{const {error}=await supabaseClient.from("folders").update({parent_id:parentId}).eq("id",folderId);if(error)throw error;await loadCloudGameContent(activeGame.id);if(parentId){activeFolder=parentId;activeSubfolder=folderId;expandedFolders.add(parentId)}else{activeFolder=folderId;activeSubfolder=null;expandedFolders.add(folderId)}renderFolders();renderNotes();showToast(parentId?"Pasta transformada em subpasta!":"Subpasta transformada em pasta principal!");return true}catch(error){showToast(error.message||"Não foi possível mover a pasta.");return false}}
async function placeFolderRelative(folderId,targetId,after=false){const source=findFolderLocation(folderId),target=findFolderLocation(targetId);if(!source||!target||target.isRoot||String(folderId)===String(targetId))return false;if(source.isRoot&&(subfolders[source.item.id]||[]).length){showToast("Mova primeiro as subpastas desta pasta antes de colocá-la dentro de outra.");return false}const parentId=target.parentId,ordered=(subfolders[parentId]||[]).filter(item=>String(item.id)!==String(folderId)),targetIndex=ordered.findIndex(item=>String(item.id)===String(targetId));ordered.splice(Math.max(0,targetIndex+(after?1:0)),0,source.item);try{const results=await Promise.all(ordered.map((item,index)=>supabaseClient.from("folders").update({parent_id:parentId,position:index}).eq("id",item.id)));const failed=results.find(result=>result.error);if(failed)throw failed.error;await loadCloudGameContent(activeGame.id);activeFolder=parentId;activeSubfolder=folderId;expandedFolders.add(parentId);renderFolders();renderNotes();showToast("Ordem das subpastas atualizada!");return true}catch(error){showToast(error.message||"Não foi possível reordenar as subpastas.");return false}}
function itemMatchesActiveFilters(item){return(activeTypeFilter==="all"||item.type===activeTypeFilter)&&(activeStatusFilter==="all"||(item.type==="task"&&(activeStatusFilter==="done"?item.done:!item.done)))}
function setupFolderDragging(element){
 const folderId=element.dataset.dragFolder,isTouchDevice=matchMedia("(hover: none) and (pointer: coarse)").matches;
 element.draggable=false;
 let startX=0,startY=0,mousePressed=false;
 const activate=()=>{if(touchFolderDrag)return;touchFolderDrag={id:folderId};suppressFolderClick=true;element.classList.add("is-dragging");document.body.classList.add("folder-touch-dragging");if(isTouchDevice&&navigator.vibrate)navigator.vibrate(35)};
 const updateTarget=(x,y)=>{const hit=document.elementFromPoint(x,y),subfolderTarget=hit?.closest("[data-subfolder]")||null,next=subfolderTarget||hit?.closest("[data-drop-folder],#root-folder-drop")||null;document.querySelectorAll(".drop-target,.drop-before,.drop-after").forEach(item=>item.classList.remove("drop-target","drop-before","drop-after"));touchDropTarget=next;touchDropPosition=null;if(!next||String(next.dataset.dragFolder||next.dataset.dropFolder||"")===String(folderId))return;if(subfolderTarget){const rect=subfolderTarget.getBoundingClientRect();touchDropPosition=y<rect.top+rect.height/2?"before":"after";subfolderTarget.classList.add(touchDropPosition==="before"?"drop-before":"drop-after")}else next.classList.add("drop-target")};
 const finish=async()=>{clearTimeout(touchFolderTimer);mousePressed=false;if(!touchFolderDrag)return;const destination=touchDropTarget,position=touchDropPosition,rootDrop=destination?.id==="root-folder-drop",targetId=destination?.dataset.subfolder,parentId=rootDrop?null:destination?.dataset.dropFolder;clearFolderDropState();if(targetId&&String(targetId)!==String(folderId))await placeFolderRelative(folderId,targetId,position==="after");else if(destination&&(rootDrop||String(parentId)!==String(folderId)))await moveFolder(folderId,parentId);setTimeout(()=>{suppressFolderClick=false},250)};
 element.addEventListener("pointerdown",event=>{if(event.pointerType!=="mouse"||event.button!==0)return;mousePressed=true;startX=event.clientX;startY=event.clientY;element.setPointerCapture(event.pointerId);clearTimeout(touchFolderTimer);touchFolderTimer=setTimeout(activate,250)});
 element.addEventListener("pointermove",event=>{if(event.pointerType!=="mouse"||!mousePressed)return;if(!touchFolderDrag&&Math.hypot(event.clientX-startX,event.clientY-startY)>5)activate();if(touchFolderDrag){event.preventDefault();updateTarget(event.clientX,event.clientY)}});
 element.addEventListener("pointerup",event=>{if(event.pointerType==="mouse")finish()});
 element.addEventListener("pointercancel",()=>{mousePressed=false;clearFolderDropState();setTimeout(()=>{suppressFolderClick=false},250)});
 element.addEventListener("touchstart",event=>{if(event.touches.length!==1)return;const touch=event.touches[0];startX=touch.clientX;startY=touch.clientY;clearTimeout(touchFolderTimer);touchFolderTimer=setTimeout(activate,400)},{passive:true});
 element.addEventListener("touchmove",event=>{const touch=event.touches[0];if(!touch)return;if(!touchFolderDrag){if(Math.hypot(touch.clientX-startX,touch.clientY-startY)>10)clearTimeout(touchFolderTimer);return}event.preventDefault();updateTarget(touch.clientX,touch.clientY)},{passive:false});
 element.addEventListener("touchend",finish,{passive:true});
 element.addEventListener("touchcancel",()=>{clearFolderDropState();setTimeout(()=>{suppressFolderClick=false},250)},{passive:true});
 element.addEventListener("contextmenu",event=>{if(touchFolderDrag||isTouchDevice)event.preventDefault()});
}
function renderFolders(){
 $("#folder-list").innerHTML=folders.map(f=>{
  const children=subfolders[f.id]||[],expanded=expandedFolders.has(f.id),items=folderItems(f.id),filteredItems=items.filter(itemMatchesActiveFilters);
  return `<div class="folder-group ${expanded?"expanded":""}" data-drop-folder="${f.id}"><div class="folder-row"><button class="expand-btn" type="button" data-expand="${f.id}" aria-label="${expanded?"Recolher":"Expandir"} ${escapeHtml(f.name)}"><span>›</span></button><button class="folder-item ${f.id===activeFolder&&!activeSubfolder?"active":""}" type="button" draggable="true" data-drag-folder="${f.id}" data-folder="${f.id}"><span class="folder-icon" style="--folder-color:${f.color}"></span><span class="folder-name">${escapeHtml(f.name)}</span><span class="folder-count">${filteredItems.length}</span></button></div><div class="subfolder-list">${children.map(child=>`<button class="subfolder-item ${f.id===activeFolder&&child.id===activeSubfolder?"active":""}" style="--subfolder-color:${child.color||f.color}" type="button" draggable="true" data-drag-folder="${child.id}" data-parent="${f.id}" data-subfolder="${child.id}"><span class="folder-name">${escapeHtml(child.name)}</span><span class="subfolder-count">${filteredItems.filter(n=>n.subfolder===child.id).length}</span></button>`).join("")}</div></div>`;
 }).join("");
 document.querySelectorAll("[data-expand]").forEach(btn=>btn.addEventListener("click",()=>{const id=btn.dataset.expand;expandedFolders.has(id)?expandedFolders.delete(id):expandedFolders.add(id);renderFolders()}));
 document.querySelectorAll("[data-folder]").forEach(btn=>btn.addEventListener("click",()=>{if(suppressFolderClick)return;activeFolder=btn.dataset.folder;activeSubfolder=null;expandedFolders.add(activeFolder);renderFolders();renderNotes()}));
 document.querySelectorAll("[data-subfolder]").forEach(btn=>btn.addEventListener("click",()=>{if(suppressFolderClick)return;activeFolder=btn.dataset.parent;activeSubfolder=btn.dataset.subfolder;expandedFolders.add(activeFolder);renderFolders();renderNotes()}));
 document.querySelectorAll("[data-drag-folder]").forEach(setupFolderDragging);
 document.querySelectorAll("[data-drop-folder]").forEach(target=>{target.addEventListener("dragover",event=>{if(!draggedFolderId||String(target.dataset.dropFolder)===String(draggedFolderId))return;event.preventDefault();event.dataTransfer.dropEffect="move";target.classList.add("drop-target")});target.addEventListener("dragleave",event=>{if(!target.contains(event.relatedTarget))target.classList.remove("drop-target")});target.addEventListener("drop",async event=>{event.preventDefault();const id=draggedFolderId||event.dataTransfer.getData("text/plain"),parentId=target.dataset.dropFolder;clearFolderDropState();if(id&&String(id)!==String(parentId))await moveFolder(id,parentId)})});
 const rootDrop=$("#root-folder-drop");rootDrop.ondragover=event=>{if(!draggedFolderId)return;event.preventDefault();event.dataTransfer.dropEffect="move";rootDrop.classList.add("drop-target")};rootDrop.ondragleave=()=>rootDrop.classList.remove("drop-target");rootDrop.ondrop=async event=>{event.preventDefault();const id=draggedFolderId||event.dataTransfer.getData("text/plain");clearFolderDropState();if(id)await moveFolder(id,null)};
}
function renderNotes(){
 const folder=folders.find(f=>f.id===activeFolder),child=(subfolders[activeFolder]||[]).find(s=>s.id===activeSubfolder),allItems=visibleItems(),tasks=allItems.filter(n=>n.type==="task"),done=tasks.filter(n=>n.done).length;
 if(!folder){$("#folder-title").textContent="Nenhuma pasta";$("#folder-eyebrow").textContent="ORGANIZE ESTE JOGO";$("#progress-text").textContent="0 tarefas";$("#progress-bar").style.width="0%";$("#notes-list").innerHTML='<div class="empty-state"><span>⌁</span><h2>Crie sua primeira pasta</h2><p>Use o botão + na seção de pastas para começar.</p></div>';return}
 const query=$("#content-search").value.trim().toLowerCase();
 const items=allItems.filter(item=>itemMatchesActiveFilters(item)&&(!query||`${item.title} ${item.content}`.toLowerCase().includes(query)));
 $("#folder-title").textContent=child?child.name:folder.name;$("#folder-eyebrow").textContent=child?`${folder.name.toUpperCase()} · SUBPASTA`:`PASTA · ${allItems.length} ITENS`;
 $("#progress-text").textContent=`${done} de ${tasks.length} tarefas concluídas`;$("#progress-bar").style.width=`${tasks.length?done/tasks.length*100:0}%`;
 $("#notes-list").innerHTML=items.length?items.map(n=>`<article class="note-item ${n.type==="note"?"plain-note":n.done?"completed":""}">${n.type==="note"?`<span class="note-symbol" aria-hidden="true">✎</span>`:`<button class="check-btn" type="button" data-note="${n.id}" aria-label="${n.done?"Marcar como pendente":"Marcar como concluído"}">${n.done?"✓":""}</button>`}<div class="note-copy"><h3>${escapeHtml(n.title)}</h3><p>${escapeHtml(n.content)}</p>${n.image?`<img class="note-attachment" src="${escapeHtml(n.image)}" alt="Imagem anexada a ${escapeHtml(n.title)}" data-expand-image data-image-title="${escapeHtml(n.title)}" tabindex="0" role="button" />`:""}</div><div class="note-side"><span class="note-meta">${n.type==="note"?"ANOTAÇÃO · ":""}${n.date}</span><button class="note-action" type="button" data-edit-note="${n.id}" aria-label="Editar ${escapeHtml(n.title)}">•••</button></div></article>`).join(""):`<div class="empty-state"><span>⌁</span><h2>Nenhum item neste filtro</h2><p>Altere os filtros, a busca ou crie um novo item.</p></div>`;
 document.querySelectorAll("[data-note]").forEach(btn=>btn.addEventListener("click",()=>toggleNote(btn.dataset.note)));
 document.querySelectorAll("[data-edit-note]").forEach(btn=>btn.addEventListener("click",()=>openNoteDialog(btn.dataset.editNote)));
 document.querySelectorAll("[data-expand-image]").forEach(image=>{const open=()=>openImageLightbox(image.src,image.dataset.imageTitle);image.addEventListener("click",open);image.addEventListener("keydown",event=>{if(event.key==="Enter"||event.key===" "){event.preventDefault();open()}})});
}
function openImageLightbox(src,title){$("#image-lightbox-content").src=src;$("#image-lightbox-content").alt=`Imagem ampliada de ${title}`;$("#image-lightbox-caption").textContent=title;$("#image-lightbox").showModal()}
async function toggleNote(id){const item=folderItems(activeFolder).find(n=>String(n.id)===String(id));if(item){const next=!item.done,{error}=await supabaseClient.from("note_items").update({is_completed:next}).eq("id",item.id);if(error){showToast("Não foi possível atualizar a tarefa.");return}item.done=next;syncActiveGameTaskProgress();renderFolders();renderNotes();showToast(item.done?"Tarefa concluída!":"Tarefa reaberta.")}}
function saveNotes(){localStorage.setItem("checkpoint-notes",JSON.stringify(notes))}
function saveSubfolders(){try{localStorage.setItem("checkpoint-subfolders",JSON.stringify(subfolders));return true}catch(error){showToast("Não foi possível salvar. Recarregue a página e tente novamente.");return false}}
function saveStructure(){try{localStorage.setItem("checkpoint-folders",JSON.stringify(folders));localStorage.setItem("checkpoint-subfolders",JSON.stringify(subfolders));localStorage.setItem("checkpoint-notes",JSON.stringify(notes));return true}catch(error){showToast("Não foi possível salvar a estrutura. Tente novamente.");return false}}
function showToast(message){const toast=$("#toast");toast.textContent=message;toast.classList.add("show");clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>toast.classList.remove("show"),2300)}
function friendlyAuthError(error){const code=error?.code||"",message=(error?.message||"").toLowerCase();if(code==="over_email_send_rate_limit"||message.includes("email rate limit"))return "O limite temporário de e-mails foi atingido. Aguarde até uma hora antes de tentar novamente.";if(code==="over_request_rate_limit"||message.includes("too many requests"))return "Muitas tentativas em pouco tempo. Aguarde alguns minutos e tente novamente.";if(code==="email_address_not_authorized")return "Este endereço ainda não está autorizado pelo provedor de testes. Configure um SMTP próprio para enviar a qualquer usuário.";if(code==="invalid_credentials")return "E-mail ou senha incorretos.";if(code==="email_not_confirmed")return "Confirme seu e-mail antes de entrar.";return error?.message||"Não foi possível concluir. Tente novamente."}
function startEmailCooldown(button,label,seconds=60){button.disabled=true;let remaining=seconds;button.textContent=`Aguarde ${remaining}s`;const timer=setInterval(()=>{remaining-=1;if(remaining<=0){clearInterval(timer);button.disabled=false;button.textContent=label}else button.textContent=`Aguarde ${remaining}s`},1000)}
function authMessage(message,success=false){const element=$("#auth-message");element.textContent=message;element.classList.toggle("success",success)}
function hideAuthPanels(){["#auth-entry","#confirmation-pending","#confirmation-result","#forgot-password-screen","#recovery-sent","#reset-password-screen","#password-reset-success"].forEach(selector=>$(selector).hidden=true)}
function showAuthEntry(){currentSession=null;authResultVisible=false;hideAuthPanels();$("#auth-entry").hidden=false;setAuthMode("login")}
function setAuthMode(mode){authMode=mode;const register=mode==="register";hideAuthPanels();$("#auth-entry").hidden=false;$("#auth-title").textContent=register?"Criar conta":"Entrar";$("#auth-subtitle").textContent=register?"Crie sua conta para sincronizar sua jornada.":"Acesse sua biblioteca e continue de onde parou.";$("#auth-submit").textContent=register?"Criar minha conta":"Entrar";$("#auth-confirm-wrap").hidden=!register;$("#auth-password-confirm").required=register;$("#auth-password").autocomplete=register?"new-password":"current-password";$("#forgot-password").hidden=register;$("#auth-login-tab").classList.toggle("active",!register);$("#auth-register-tab").classList.toggle("active",register);authMessage("")}
