$("#edit-folder-form").addEventListener("submit",async event=>{event.preventDefault();const child=(subfolders[activeFolder]||[]).find(item=>item.id===activeSubfolder),folder=folders.find(item=>item.id===activeFolder),target=child||folder,name=$("#edit-folder-name").value.trim(),color=$("#edit-folder-color").value,parentId=$("#edit-folder-parent").value||null;if(!target||!name)return;if(!child&&parentId&&(subfolders[target.id]||[]).length){showToast("Mova primeiro as subpastas desta pasta antes de colocá-la dentro de outra.");return}try{const {error}=await supabaseClient.from("folders").update({name,color_code:color,parent_id:parentId}).eq("id",target.id);if(error)throw error;await loadCloudGameContent(activeGame.id);if(parentId){activeFolder=parentId;activeSubfolder=target.id;expandedFolders.add(parentId)}else{activeFolder=target.id;activeSubfolder=null;expandedFolders.add(target.id)}$("#edit-folder-dialog").close();renderFolders();renderNotes();showToast(parentId?"Pasta salva como subpasta!":"Pasta principal atualizada!")}catch(error){showToast(error.message||"Não foi possível atualizar a pasta.")}});
$("#delete-folder").addEventListener("click",async()=>{const isChild=Boolean(activeSubfolder),child=(subfolders[activeFolder]||[]).find(item=>item.id===activeSubfolder),folder=folders.find(item=>item.id===activeFolder),target=child||folder,name=target.name,relatedItems=isChild?folderItems(activeFolder).filter(item=>item.subfolder===activeSubfolder):folderItems(activeFolder),count=relatedItems.length;if(!confirm(`Excluir ${name}, ${count} item(ns) e suas imagens? Esta ação não pode ser desfeita.`))return;if(!isChild&&folders.length===1){showToast("Mantenha pelo menos uma pasta principal.");return}const {error}=await supabaseClient.from("folders").delete().eq("id",target.id);if(error){showToast("Não foi possível excluir a pasta.");return}const removed=await deleteStoredImages(relatedItems.map(item=>item.imageRef));await loadCloudGameContent(activeGame.id);$("#edit-folder-dialog").close();renderFolders();renderNotes();showToast(removed?"Pasta e imagens excluídas da nuvem.":"Pasta excluída, mas alguma imagem não pôde ser removida do R2.")});

function relativeTime(value){const seconds=Math.max(0,Math.floor((Date.now()-new Date(value).getTime())/1000));if(seconds<60)return"agora";if(seconds<3600)return`há ${Math.floor(seconds/60)} min`;if(seconds<86400)return`há ${Math.floor(seconds/3600)} h`;const days=Math.floor(seconds/86400);return days===1?"ontem":`há ${days} dias`}
function activityRow(icon,title,detail){return`<article class="activity-row"><span class="activity-row-icon" aria-hidden="true">${icon}</span><div class="activity-row-copy"><strong>${escapeHtml(title)}</strong><small>${escapeHtml(detail)}</small></div></article>`}
async function loadActivityDashboard(){const pendingBox=$("#pending-activity"),recentBox=$("#recent-activity");pendingBox.innerHTML=recentBox.innerHTML='<p class="activity-empty">Carregando...</p>';try{const [gamesResult,tasksResult,pendingResult,recentGamesResult,recentItemsResult]=await Promise.all([supabaseClient.from("games").select("id,status,is_completed"),supabaseClient.from("note_items").select("id,item_type,is_completed"),supabaseClient.from("note_items").select("title,updated_at").eq("item_type","task").eq("is_completed",false).order("updated_at",{ascending:false}).limit(6),supabaseClient.from("games").select("title,updated_at").order("updated_at",{ascending:false}).limit(5),supabaseClient.from("note_items").select("title,item_type,is_completed,updated_at").order("updated_at",{ascending:false}).limit(8)]);for(const result of [gamesResult,tasksResult,pendingResult,recentGamesResult,recentItemsResult])if(result.error)throw result.error;const gameRows=gamesResult.data||[],taskRows=(tasksResult.data||[]).filter(item=>item.item_type==="task"),pendingRows=pendingResult.data||[];$("#stat-games").textContent=gameRows.length;$("#stat-playing").textContent=gameRows.filter(game=>game.status==="playing"&&!game.is_completed).length;$("#stat-pending").textContent=taskRows.filter(item=>!item.is_completed).length;$("#stat-done").textContent=taskRows.filter(item=>item.is_completed).length;pendingBox.innerHTML=pendingRows.length?pendingRows.map(item=>activityRow("□",item.title,`Tarefa pendente · ${relativeTime(item.updated_at)}`)).join(""):'<p class="activity-empty">Nenhuma tarefa pendente. Tudo em dia!</p>';const recent=[...(recentGamesResult.data||[]).map(item=>({title:item.title,detail:`Jogo atualizado · ${relativeTime(item.updated_at)}`,date:item.updated_at,icon:"▦"})),...(recentItemsResult.data||[]).map(item=>({title:item.title,detail:`${item.item_type==="task"?(item.is_completed?"Tarefa concluída":"Tarefa atualizada"):"Anotação atualizada"} · ${relativeTime(item.updated_at)}`,date:item.updated_at,icon:item.item_type==="task"?(item.is_completed?"✓":"□"):"✎"}))].sort((a,b)=>new Date(b.date)-new Date(a.date)).slice(0,8);recentBox.innerHTML=recent.length?recent.map(item=>activityRow(item.icon,item.title,item.detail)).join(""):'<p class="activity-empty">Sua atividade aparecerá aqui.</p>'}catch(error){pendingBox.innerHTML=recentBox.innerHTML='<p class="activity-empty">Não foi possível carregar a atividade agora.</p>'}}
async function cloudBackupPayload(){const [gameResult,folderResult,itemResult]=await Promise.all([supabaseClient.from("games").select("*"),supabaseClient.from("folders").select("*"),supabaseClient.from("note_items").select("*")]);for(const result of [gameResult,folderResult,itemResult])if(result.error)throw result.error;const clean=rows=>rows.map(({user_id,...row})=>row);return{app:"checkpoint",version:3,exportedAt:new Date().toISOString(),games:clean(gameResult.data||[]),folders:clean(folderResult.data||[]),noteItems:clean(itemResult.data||[])}}
async function updateDataSummary(){try{const [payload,usage]=await Promise.all([cloudBackupPayload(),r2Request("/usage")]),used=formatBytes(usage.totalBytes),limit=formatBytes(usage.maxBucketBytes);$("#data-summary").textContent=`${payload.games.length} jogo(s), ${payload.folders.length} pasta(s) e ${payload.noteItems.length} item(ns). Imagens: ${used} de ${limit} usados.`}catch(error){$("#data-summary").textContent="Não foi possível calcular o resumo agora."}}
$("#export-data").addEventListener("click",async event=>{const button=event.currentTarget;button.disabled=true;button.textContent="Preparando...";try{const payload=await cloudBackupPayload(),blob=new Blob([JSON.stringify(payload,null,2)],{type:"application/json"}),link=document.createElement("a");link.href=URL.createObjectURL(blob);link.download=`checkpoint-backup-${new Date().toISOString().slice(0,10)}.json`;link.click();URL.revokeObjectURL(link.href);showToast("Backup completo exportado!")}catch(error){showToast("Não foi possível exportar o backup.")}finally{button.disabled=false;button.textContent="↓ Exportar backup"}});
$("#import-data").addEventListener("change",async event=>{const file=event.target.files[0];if(!file)return;try{if(file.size>5*1024*1024)throw new Error("large");const data=JSON.parse(await file.text());if(data.app!=="checkpoint"||data.version!==3||!Array.isArray(data.games)||!Array.isArray(data.folders)||!Array.isArray(data.noteItems))throw new Error("invalid");if(!confirm("Este backup será adicionado à sua conta sem apagar os dados atuais. Continuar?"))return;const gameIds=new Map(),folderIds=new Map();for(const oldGame of data.games){const {id,created_at,updated_at,...game}=oldGame,{data:created,error}=await supabaseClient.from("games").insert(game).select("id").single();if(error)throw error;gameIds.set(id,created.id)}for(const oldFolder of data.folders.filter(folder=>!folder.parent_id)){const {id,game_id,created_at,updated_at,...folder}=oldFolder,{data:created,error}=await supabaseClient.from("folders").insert({...folder,game_id:gameIds.get(game_id)}).select("id").single();if(error)throw error;folderIds.set(id,created.id)}for(const oldFolder of data.folders.filter(folder=>folder.parent_id)){const {id,game_id,parent_id,created_at,updated_at,...folder}=oldFolder,{data:created,error}=await supabaseClient.from("folders").insert({...folder,game_id:gameIds.get(game_id),parent_id:folderIds.get(parent_id)}).select("id").single();if(error)throw error;folderIds.set(id,created.id)}for(const oldItem of data.noteItems){const {id,folder_id,created_at,updated_at,...item}=oldItem,{error}=await supabaseClient.from("note_items").insert({...item,folder_id:folderIds.get(folder_id)});if(error)throw error}await loadCloudGames();await updateDataSummary();showToast("Backup adicionado à sua conta!")}catch(error){showToast(error.message==="large"?"O backup excede o limite de 5 MB.":"Backup inválido ou não foi possível importá-lo.")}finally{event.target.value=""}});
document.querySelector('[data-view="activity"]').addEventListener("click",loadActivityDashboard);
document.querySelector('[data-view="data"]').addEventListener("click",updateDataSummary);

