$("#banner-form").addEventListener("submit",async event=>{event.preventDefault();const file=$("#banner-file").files[0],url=$("#banner-url").value.trim();if(!file&&!url){showToast("Informe uma URL ou selecione uma imagem.");return}if(file&&!optimizedBannerImage){showToast("Aguarde a otimização do banner.");return}const submit=event.submitter,oldRef=activeGame.coverRef||"";submit.disabled=true;submit.textContent="Salvando...";try{const uploaded=optimizedBannerImage?await uploadOptimizedImage(optimizedBannerImage):null,storedValue=uploaded?.ref||url,displayUrl=uploaded?.url||url,{error}=await supabaseClient.from("games").update({cover_image_url:storedValue}).eq("id",activeGame.id);if(error)throw error;if(oldRef&&oldRef!==storedValue)await deleteStoredImage(oldRef);activeGame.coverRef=storedValue;activeGame.cover=displayUrl;$("#hero-image").style.backgroundImage=`url("${displayUrl}")`;$("#banner-dialog").close();renderGames();showToast("Banner sincronizado no R2!")}catch(error){showToast(error.message||"Não foi possível salvar o banner.")}finally{submit.disabled=false;submit.textContent="Salvar banner"}});
function setAvatar(imageElement,initialElement,url,name){imageElement.hidden=!url;initialElement.hidden=Boolean(url);if(url)imageElement.src=url;else imageElement.removeAttribute("src");initialElement.textContent=(name.trim()[0]||"E").toUpperCase()}
function renderProfile(){const name=localProfile.displayName||"Meu perfil";$("#sidebar-profile-name").textContent=name;$("#profile-preview-name").textContent=name;setAvatar($("#sidebar-avatar-image"),$("#sidebar-avatar-initial"),localProfile.avatarUrl,name);setAvatar($("#profile-avatar-image"),$("#profile-avatar-initial"),localProfile.avatarUrl,name)}
function openProfilePage(){const current=document.querySelector(".view.active")?.id?.replace("-view","");if(current&&current!=="profile")profileReturnView=current;optimizedProfileImage=null;$("#profile-form").reset();$("#profile-display-name").value=localProfile.displayName||"";$("#profile-avatar-url").value=localProfile.avatarRef?.startsWith("http")?localProfile.avatarRef:"";$("#profile-avatar-status").hidden=true;renderProfile();setView("profile");document.activeElement?.blur()}
function closeProfilePage(){setView(profileReturnView||"library")}
