$("#profile-form").addEventListener("submit",async event=>{event.preventDefault();const displayName=$("#profile-display-name").value.trim(),rawUrl=$("#profile-avatar-url").value.trim(),avatarUrl=normalizeHttpUrl(rawUrl),submit=event.submitter;if(!displayName)return;if(rawUrl&&!avatarUrl){showToast("Use uma URL de foto iniciada por http:// ou https://.");return}if($("#profile-avatar-file").files[0]&&!optimizedProfileImage){showToast("Aguarde a otimização da foto.");return}const oldRef=localProfile.avatarRef||"";submit.disabled=true;submit.textContent="Salvando...";try{const uploaded=optimizedProfileImage?await uploadOptimizedImage(optimizedProfileImage):null,storedAvatar=uploaded?.ref||avatarUrl||oldRef||null,displayAvatar=uploaded?.url||avatarUrl||localProfile.avatarUrl||"";if(currentSession){const {error:authError}=await supabaseClient.auth.updateUser({data:{display_name:displayName,avatar_url:storedAvatar}});if(authError)throw authError;const {error:profileError}=await supabaseClient.from("profiles").update({display_name:displayName,avatar_url:storedAvatar}).eq("id",currentSession.user.id);if(profileError)throw profileError}if(oldRef&&oldRef!==storedAvatar)await deleteStoredImage(oldRef);localProfile={displayName,avatarRef:storedAvatar||"",avatarUrl:displayAvatar};localStorage.setItem("checkpoint-profile",JSON.stringify(localProfile));renderProfile();closeProfilePage();showToast(optimizedProfileImage?"Foto salva no R2!":"Perfil atualizado!")}catch(error){showToast(error.message||"Não foi possível atualizar o perfil.")}finally{submit.disabled=false;submit.textContent="Salvar perfil"}});
