async function sendRecoveryEmail(email,button,messageElement){button.disabled=true;button.textContent="Enviando...";const {error}=await supabaseClient.auth.resetPasswordForEmail(email,{redirectTo:`${appBaseUrl}?recovery=1`});button.disabled=false;button.textContent="Enviar link de recuperação";if(error){messageElement.textContent=friendlyAuthError(error);return false}return true}
$("#forgot-password-form").addEventListener("submit",async event=>{event.preventDefault();const email=$("#recovery-email").value.trim();if(!await sendRecoveryEmail(email,$("#send-recovery"),$("#recovery-message")))return;pendingConfirmationEmail=email;hideAuthPanels();$("#recovery-sent").hidden=false;$("#recovery-sent-email").textContent=email;$("#recovery-sent-message").textContent=""});
