$("#recovery-password-form").addEventListener("submit",async event=>{event.preventDefault();const password=$("#recovery-new-password").value,confirmation=$("#recovery-new-password-confirm").value,submit=$("#save-recovery-password"),message=$("#recovery-password-message");if(password!==confirmation){message.textContent="As senhas não são iguais.";return}submit.disabled=true;submit.textContent="Salvando...";const {error}=await supabaseClient.auth.updateUser({password});if(error){message.textContent=error.message;submit.disabled=false;submit.textContent="Salvar nova senha";return}recoveryFlowActive=false;authResultVisible=true;hideAuthPanels();$("#password-reset-success").hidden=false;await supabaseClient.auth.signOut({scope:"local"});submit.disabled=false;submit.textContent="Salvar nova senha"});
